=== AudioHub ===
import AVFoundation
import ObjCExceptionTrap

/// Owns the microphone. A single input tap fans each captured buffer out to
/// every consumer (the laughter detector *and* the speech recogniser), so the
/// two never fight over the input node.
///
/// The `AVAudioEngine` is **rebuilt on every start** rather than held for the
/// process lifetime — see `prepareFormat()` for why that is load-bearing and not
/// tidiness. Because the engine instance changes, this class also owns the
/// `.AVAudioEngineConfigurationChange` observation and republishes it through
/// `onConfigurationChange`: an observer registered against a replaced engine goes
/// quiet, and a quiet config-change observer means the app stops noticing that
/// its microphone disappeared.
final class AudioHub {
    private var engine: AVAudioEngine
    private var configObserver: NSObjectProtocol?

    /// Called for every captured buffer, on the audio thread.
    var onBuffer: ((AVAudioPCMBuffer, AVAudioTime) -> Void)?

    /// Called on the main queue when CoreAudio reports that the current engine's
    /// configuration changed (device added, removed, or switched under us).
    var onConfigurationChange: (() -> Void)?

    /// The input format currently in use (valid only once `start(format:)` ran).
    private(set) var activeFormat: AVAudioFormat?

    var isRunning: Bool { engine.isRunning }

    init() {
        engine = Self.makeEngine()
        observeConfigurationChange()
    }

    /// Build an engine that is safe to `prepare()`.
    ///
    /// `AVAudioEngine` initializes its graph inside `prepare()` and asserts that
    /// at least one node is attached — `inputNode != nullptr || outputNode !=
    /// nullptr` — raising an uncatchable NSException when none is. A freshly
    /// constructed engine has none: `inputNode` is created lazily *on first
    /// access*, and touching the property is what attaches it. So materialize it
    /// here, as part of building an engine, rather than leaving it to a call
    /// order somewhere else.
    ///
    /// The pre-rebuild code survived only by accident: `requestListening()` calls
    /// `stop()`, which reaches `engine.inputNode.removeTap(onBus: 0)` and
    /// materialized the node on the single long-lived engine long before any
    /// `prepare()`. Rebuilding the engine after that call removed the accident,
    /// and every launch crashed one second in. (#72)
    private static func makeEngine() -> AVAudioEngine {
        let engine = AVAudioEngine()
        _ = engine.inputNode   // attaches it; do not "simplify" this away
        return engine
    }

    deinit {
        if let observer = configObserver {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    /// Build a fresh engine and return its validated live input format, **without**
    /// starting capture. The input node's format is only reliable after prepare;
    /// returning it first lets the detector be configured to match *before* any
    /// audio flows (the analyzer must exist before buffers arrive, or the first
    /// buffers are dropped and analysis can fail to start).
    ///
    /// The engine is replaced here rather than reused, and that is the fix for
    /// #61. An `AVAudioEngine` caches the input hardware format when its input
    /// node is first materialized, and the cache does not follow the device: after
    /// CoreAudio tears the input down — a USB mic re-enumerating, or coreaudiod
    /// dropping its contexts when the display sleeps — `inputNode.outputFormat(
    /// forBus: 0)` keeps reporting the *old* rate. `installTap` validates against
    /// the freshly-queried hardware format instead, the two disagree, and it
    /// raises an uncatchable NSException. That killed the app on every single
    /// configuration change (six for six over fifteen days) — not the rare race
    /// the previous guard assumed, because comparing the stale cache against
    /// itself always passed. A new engine reads the hardware fresh, so the guard
    /// in `start(format:)` is meaningful again and the two formats agree.
    func prepareFormat() throws -> AVAudioFormat {
        renewEngine()
        // Trapped as well as installTap: #59 wrapped only the tap install, and
        // prepare() then raised from a path with no trap in it at all. Anything
        // that can raise on the way to capture gets the same treatment. (#72)
        try ObjCExceptionTrap.run { engine.prepare() }
        return try validatedFormat()
    }

    /// The tap format, checked against the *hardware* format that `installTap`
    /// asserts on.
    ///
    /// Read `inputFormat(forBus: 0)`, not `outputFormat`: `outputFormat` is the
    /// bus's output format, and with the input device torn down it still reports
    /// a plausible 48 kHz while `inputFormat` correctly reports 0. Checking
    /// `outputFormat` therefore could not detect an absent microphone at all — it
    /// waved through starts that could never succeed and left `installTap` to
    /// raise, which is what the exception trap kept catching once a minute while
    /// the displays slept. Requiring the two to agree means `installTap` is never
    /// reached in the mismatch state. (#76)
    private func validatedFormat() throws -> AVAudioFormat {
        let input = engine.inputNode
        let hardware = input.inputFormat(forBus: 0)
        let bus = input.outputFormat(forBus: 0)
        guard hardware.sampleRate > 0, hardware.channelCount > 0 else {
            throw NSError(domain: "LaughCounter", code: 1, userInfo: [
                NSLocalizedDescriptionKey:
                    "no input hardware — the microphone is not available "
                    + "(sampleRate=\(hardware.sampleRate), channels=\(hardware.channelCount))",
            ])
        }
        guard hardware.sampleRate == bus.sampleRate,
              hardware.channelCount == bus.channelCount else {
            throw NSError(domain: "LaughCounter", code: 2, userInfo: [
                NSLocalizedDescriptionKey:
                    "input format unsettled "
                    + "(hardware \(hardware.sampleRate)Hz/\(hardware.channelCount)ch, "
                    + "bus \(bus.sampleRate)Hz/\(bus.channelCount)ch)",
            ])
        }
        return bus
    }

    /// Install the tap and start capture, using a format from `prepareFormat()`.
    func start(format: AVAudioFormat) throws {
        let input = engine.inputNode
        // Re-validate against the hardware immediately before the tap: the device
        // can still vanish between prepareFormat() and here (dock unplug,
        // wake-time re-enumeration), and a mismatch reaching installTap is what
        // raises. Checking the same pair as prepareFormat did, because the bus
        // format alone cannot tell an absent device from a present one. (#76)
        let live = try validatedFormat()
        guard live.sampleRate == format.sampleRate,
              live.channelCount == format.channelCount else {
            throw NSError(domain: "LaughCounter", code: 3, userInfo: [
                NSLocalizedDescriptionKey:
                    "input device changed between prepare and start "
                    + "(expected \(format.sampleRate)Hz/\(format.channelCount)ch, "
                    + "live \(live.sampleRate)Hz/\(live.channelCount)ch)",
            ])
        }
        input.removeTap(onBus: 0)   // no-op if none installed; keeps restart clean
        // Backstop: installTap raises an *uncatchable* NSException if its format
        // disagrees with the live hardware, and Swift cannot catch one — it aborts
        // the process, skipping the tap teardown in applicationWillTerminate and
        // leaving the IOProc registered, which is exactly what wedges a USB webcam
        // mic until it is physically re-plugged. This is not theoretical and not
        // dead code: it demonstrably caught that exception once a minute while the
        // displays slept, which is the only reason the app survived. The guard
        // above should now keep us off that path; this stays because there is no
        // atomic API and being wrong here costs the microphone.
        try ObjCExceptionTrap.run {
            input.installTap(onBus: 0, bufferSize: 8192, format: format) { [weak self] buffer, when in
                self?.onBuffer?(buffer, when)
            }
        }
        try engine.start()
        activeFormat = format
    }

    func stop() {
        engine.inputNode.removeTap(onBus: 0)
        // Unconditional: engine.stop() is safe on a non-running engine, and it also
        // releases what engine.prepare() allocated — a prepare()-then-throw path
        // (prepareFormat/configure failing before start) would otherwise leave the
        // initialized input unit holding the device.
        engine.stop()
        activeFormat = nil
    }

    /// Tear the current engine down and put a fresh one in its place. Stopping
    /// first is what keeps the release-the-mic invariant: dropping the last
    /// reference to a *running* engine would abandon its tap and IOProc on the
    /// device instead of deregistering them.
    private func renewEngine() {
        stop()
        engine = Self.makeEngine()
        observeConfigurationChange()
    }

    /// (Re)point the configuration-change observation at the current engine.
    private func observeConfigurationChange() {
        if let observer = configObserver {
            NotificationCenter.default.removeObserver(observer)
        }
        // Delivered on the main queue so the callback can touch app state directly;
        // CoreAudio posts this from whatever thread noticed the change.
        configObserver = NotificationCenter.default.addObserver(
            forName: .AVAudioEngineConfigurationChange, object: engine, queue: .main
        ) { [weak self] _ in
            self?.onConfigurationChange?()
        }
    }
}

// The privacy boundary as a check: the always-on capture path may not open an
// outbound connection. Scans the app's sources (`mac/Sources/`) for network
// *client* APIs. It matches call/import tokens rather than URL strings, so a
// comment mentioning a URL stays legal while an actual client does not.
//
// Since the Python reference was removed there is exactly one runtime tree and
// **no accepted egress at all** — detection (Sound Analysis) and speech
// recognition are both on-device, and nothing downloads a model. That makes this
// check absolute: any hit is a finding, with no optional-extra carve-out to
// reason about.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const SWIFT_CLIENTS = [
  [/\bURLSession\b/, 'URLSession'],
  [/\bNSURLConnection\b/, 'NSURLConnection'],
  [/^\s*import\s+Network\b/, 'the Network framework'],
  [/\bNWConnection\b/, 'NWConnection'],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'on-device-privacy/no-network-client',
  severity: 'blocking',
  description: 'No outbound network client in the always-on capture path (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: "the product's headline promise is that the room's audio never leaves the machine — a client in the capture path is how that promise breaks",

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const [pattern, what] of SWIFT_CLIENTS) {
          if (!pattern.test(lines[i])) continue;
          out.push({
            rule: rule.id,
            severity: rule.severity,
            file,
            line: i + 1,
            what: `${what} in the capture path (${file})`,
            why: rule.why,
            fix: 'keep analysis on-device — drop the client; the app has no accepted egress, so adding one is a product decision that belongs in RULES.md first',
            doc: rule.doc,
          });
          break;
        }
      }
    }
    return out;
  },
};

export default rule;
=== single-storage-directory ===
// "Delete the folder and it's gone" as a check: the app keeps everything it
// persists under `~/Library/Application Support/LaughCounter/`, so the only
// system directory its sources may ask macOS for is the Application Support
// one. Scans `mac/Sources/` for the APIs that *select* a search-path directory
// and requires the literal `.applicationSupportDirectory`.
//
// A whitelist, not a blacklist. Earlier sweeps left this rule as prose because
// proving "nothing lands outside the directory" looked like it needed data-flow
// tracking of every write target back to its declaration. It doesn't: every
// persistent path in the app is rooted at a `FileManager` search-path lookup,
// and there are exactly two of them (`AppLog.swift`, `Store.swift`), both
// `.applicationSupportDirectory`. Constraining the *root* constrains every path
// derived from it, and matching the allowed constant positively means a
// `SearchPathDirectory` case that doesn't exist yet is caught the day it lands —
// which an enumerate-the-bad-ones list would miss.
//
// Two deliberate consequences, both wanted:
//   - A non-literal argument (`urls(for: dir, in:)`) is a finding. Indirection
//     is exactly what would defeat the check, and no caller needs it here.
//   - The Login Item registration RULES.md carves out doesn't go through these
//     APIs at all (`SMAppService` names no directory), so it needs no exemption.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const ALLOWED = 'applicationSupportDirectory';

// The APIs that pick a system directory. `\s*` spans newlines, so a call split
// across lines (`urls(\n    for: .cachesDirectory,`) is matched too.
const SELECTORS = [
  // FileManager.default.urls(for:in:) and .url(for:in:appropriateFor:create:)
  [/\burls?\s*\(\s*for\s*:\s*([^,\s)]+)/g, 'FileManager.urls(for:)'],
  [/\bNSSearchPathForDirectoriesInDomains\s*\(\s*([^,\s)]+)/g, 'NSSearchPathForDirectoriesInDomains'],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

// `.applicationSupportDirectory`, `FileManager.SearchPathDirectory.applicationSupportDirectory`
// and a bare `applicationSupportDirectory` all name the same case.
const caseName = (token) => token.replace(/^.*\./, '');

const rule = {
  id: 'on-device-privacy/single-storage-directory',
  severity: 'blocking',
  description: 'The app asks macOS for only one directory: .applicationSupportDirectory (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: '"delete the folder and it\'s gone" is a promise a user acts on — a second storage root means the mic\'s memory of them outlives the directory they deleted',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      for (const [pattern, what] of SELECTORS) {
        pattern.lastIndex = 0;
        let m = pattern.exec(text);
        while (m !== null) {
          const token = m[1];
          if (caseName(token) !== ALLOWED) {
            out.push({
              rule: rule.id,
              severity: rule.severity,
              file,
              line: text.slice(0, m.index).split('\n').length,
              what: `${what} asks for \`${token}\`, not \`.${ALLOWED}\` (${file})`,
              why: rule.why,
              fix: `root the path at \`FileManager.default.urls(for: .${ALLOWED}, in: .userDomainMask)[0]\` and hang it off the app's existing \`LaughCounter\` directory; a second storage root is a product decision that belongs in RULES.md first`,
              doc: rule.doc,
            });
          }
          m = pattern.exec(text);
        }
      }
    }
    return out;
  },
};

export default rule;

// Red-first fixtures for the on-device-privacy checks: each rule must fire on a
// violating file and stay quiet on the repo's real, clean one. Run directly:
//
//   node --test .claudinite/local/packs/on-device-privacy/pack.test.mjs
//
// They live here rather than in tests/ (`claudinite-isolation`). The fake ctx is
// the slice of the engine's context a check actually uses — `files` and `read` —
// so these tests need neither the canon mount nor a git checkout.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import noNetworkClient from './no-network-client.mjs';
import onDeviceSpeech from './on-device-speech.mjs';
import noAudioPersistence from './no-audio-persistence.mjs';
import singleStorageDirectory from './single-storage-directory.mjs';
import noListener from './no-listener.mjs';

const repoRoot = dirname(dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))));

// Fixture ctx: an in-memory tree of { path: contents }.
const ctxOf = (tree) => ({
  files: Object.keys(tree),
  read: (path) => tree[path] ?? null,
});

// The real tree, so a rule that starts firing on the actual sources fails here.
const realCtx = (...paths) => ctxOf(Object.fromEntries(
  paths.map((p) => [p, readFileSync(join(repoRoot, p), 'utf8')])
));

test('no-network-client fires on a client in the capture path', () => {
  const findings = noNetworkClient.run(ctxOf({
    'mac/Sources/LaughCounter/Sync.swift': 'let task = URLSession.shared.dataTask(with: url)\n',
    'mac/Sources/LaughCounter/Peer.swift': 'import Foundation\nimport Network\n',
  }));
  assert.equal(findings.length, 2);
  assert.deepEqual(findings.map((f) => f.line), [1, 2]);
  assert.match(findings[0].what, /URLSession/);
  assert.match(findings[1].what, /Network framework/);
});

test('no-network-client stays quiet on the real capture path', () => {
  const findings = noNetworkClient.run(realCtx(
    'mac/Sources/LaughCounter/AudioHub.swift',
    'mac/Sources/LaughCounter/VoiceCommand.swift',
    'mac/Sources/LaughCounter/Store.swift',
    'mac/Sources/LaughCounter/LaughDetector.swift',
  ));
  assert.deepEqual(findings, []);
});

test('on-device-speech fires on a request that never opts out', () => {
  const findings = onDeviceSpeech.run(ctxOf({
    'mac/Sources/LaughCounter/VoiceCommand.swift':
      'let newRequest = SFSpeechAudioBufferRecognitionRequest()\n'
      + 'newRequest.shouldReportPartialResults = true\n',
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 1);
});

test('on-device-speech stays quiet on the real VoiceCommand', () => {
  const findings = onDeviceSpeech.run(realCtx('mac/Sources/LaughCounter/VoiceCommand.swift'));
  assert.deepEqual(findings, []);
});

test('no-audio-persistence fires on an audio-writing API in the capture path', () => {
  const findings = noAudioPersistence.run(ctxOf({
    'mac/Sources/LaughCounter/ClipWriter.swift':
      'let file = try AVAudioFile(forWriting: url, settings: format.settings)\n'
      + 'let recorder = try AVAudioRecorder(url: url, settings: settings)\n',
  }));
  assert.equal(findings.length, 2);
  assert.deepEqual(findings.map((f) => f.line), [1, 2]);
  assert.match(findings[0].what, /AVAudioFile/);
  assert.match(findings[1].what, /AVAudioRecorder/);
});
