// "Never build an `AVAudioEngine` to ask whether a microphone exists" (#88), as
// a check: `AVAudioEngine` may only be constructed in `AudioHub`.
//
// Touching `engine.inputNode` — which `AudioHub.makeEngine()` must do, because
// `prepare()` asserts a node is attached (#72) — opens the default input device
// and mints a hidden per-client aggregate device inside coreaudiod
// (`CADefaultDeviceAggregate-<pid>-<n>`). So constructing an engine is never a
// cheap read: one measured outage ran that open/create/destroy cycle ~210 times
// over 3h40m against hardware that was not there at all. `AudioDiagnostics`
// exists so nothing else has to — it answers "is there a usable mic?" with
// `AudioObjectGetPropertyData` property queries that open nothing.
//
// A positive whitelist over the construction site, not a ban list on the callers
// that shouldn't do it: a new file that reaches for an engine is caught the day
// it lands, which enumerating today's innocent files could not do.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

// The one file allowed to build one. `AudioHub` owns the microphone, rebuilds the
// engine on every start (#61), and is where `makeEngine()` keeps the
// materialize-inputNode-before-prepare() rule in one place.
const OWNER = 'mac/Sources/LaughCounter/AudioHub.swift';

// A construction, not a mention: `AVAudioEngine()` with arguments-or-not, but not
// `var engine: AVAudioEngine` and not `AVAudioEngineConfigurationChange`.
const CONSTRUCTION = /\bAVAudioEngine\s*\(/g;

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'macos-audio-lifecycle/engine-construction-confined',
  severity: 'blocking',
  description: 'Only AudioHub builds an AVAudioEngine — nothing else opens the mic to ask a question (mac/Sources/)',
  doc: '.claudinite/local/packs/macos-audio-lifecycle/RULES.md',
  why: 'constructing an engine opens the default input and churns a hidden coreaudiod aggregate device — the one mechanism by which this app could plausibly wedge a mic',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      if (file === OWNER) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      CONSTRUCTION.lastIndex = 0;
      let m = CONSTRUCTION.exec(text);
      while (m !== null) {
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: text.slice(0, m.index).split('\n').length,
          what: `builds an AVAudioEngine outside ${OWNER} (${file})`,
          why: rule.why,
          fix: 'ask AudioDiagnostics instead — `hasUsableInput` / `inputAvailability` answer from HAL property queries that open no device; if capture really is needed, route it through AudioHub, which is the single owner of the engine lifecycle',
          doc: rule.doc,
        });
        m = CONSTRUCTION.exec(text);
      }
    }
    return out;
  },
};

export default rule;

// The app's `Info.plist` may not declare `NSSupportsSuddenTermination`.
//
// The release-the-mic invariant depends on `applicationWillTerminate` actually
// running: if the process ends while the input tap's CoreAudio IOProc is still
// registered, some USB webcam mics wedge until physically re-plugged (#22).
// `main.swift` goes to the trouble of routing SIGTERM/SIGINT/SIGHUP through
// `NSApp.terminate` precisely so those paths reach that teardown. Opting into
// sudden termination tells macOS the app may be SIGKILLed at logout instead —
// which skips every one of those paths at once, silently, from a one-line plist
// edit that looks like a launch-time optimisation.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const KEY = 'NSSupportsSuddenTermination';

const inScope = (f) => f.startsWith('mac/Resources/') && f.endsWith('.plist');

const rule = {
  id: 'macos-audio-lifecycle/no-sudden-termination',
  severity: 'blocking',
  description: 'The app never opts into sudden termination — applicationWillTerminate must run (mac/Resources/*.plist)',
  doc: '.claudinite/local/packs/macos-audio-lifecycle/RULES.md',
  why: 'sudden termination lets logout SIGKILL the app past every teardown path, abandoning the input tap\'s IOProc on the device — the state that wedges a USB mic until it is re-plugged',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        if (!lines[i].includes(KEY)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: i + 1,
          what: `${file} declares ${KEY}`,
          why: rule.why,
          fix: `remove the ${KEY} key — the app must be given the chance to remove its tap and stop the engine on the way out; if a launch/quit cost is the motivation, measure it against a wedged microphone`,
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;

// "`applicationWillTerminate` is not 'every exit path' by itself", as a check.
//
// NSApplication installs no signal handlers, so a bare SIGTERM (Activity
// Monitor's Quit, `killall`), SIGINT (Ctrl-C in a dev terminal) or SIGHUP (that
// terminal closing) kills the process with no teardown — leaving the input tap's
// IOProc registered on the device, which is what wedges some USB webcam mics
// until they are re-plugged (#22). `main.swift` routes those three through
// `DispatchSourceSignal` → `NSApp.terminate`, and `signal(sig, SIG_IGN)` must
// come *before* `resume()` or a signal landing in the gap still takes the fatal
// default.
//
// Two arms, both keyed on the tree actually installing an audio tap — no tap, no
// IOProc to abandon, nothing to enforce:
//   1. some file must set up signal sources at all, covering all three signals;
//   2. in that file, SIG_IGN must precede the first resume().
//
// The ordering arm compares first-occurrence offsets rather than parsing scopes:
// the two calls sit in one small setup block in this app (a `.map` over the
// signal list), and a file that acquired a second, unrelated `resume()` above the
// setup would be flagged — a false positive that is cheap to see and cheaper than
// missing the real ordering bug, which is invisible at runtime until the one
// signal that lands in the gap.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const REQUIRED_SIGNALS = ['SIGTERM', 'SIGINT', 'SIGHUP'];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'macos-audio-lifecycle/signal-teardown-routing',
  severity: 'blocking',
  description: 'Catchable termination signals reach applicationWillTerminate, and SIG_IGN precedes resume() (mac/Sources/)',
  doc: '.claudinite/local/packs/macos-audio-lifecycle/RULES.md',
  why: 'a signal that kills the process outright skips the tap teardown and abandons the IOProc on the microphone — the wedge condition the whole lifecycle is built around',

  run(ctx) {
    const swift = ctx.files.filter(inScope);
    const read = new Map();
    for (const file of swift) {
      const text = ctx.read(file);
      if (text !== null) read.set(file, text);
    }

    // Only an app that installs an audio tap has an IOProc to abandon.
    const tapSite = [...read.entries()].find(([, text]) => /\binstallTap\s*\(/.test(text));
    if (!tapSite) return [];

    const routing = [...read.entries()]
      .filter(([, text]) => /\bmakeSignalSource\s*\(/.test(text));

    if (routing.length === 0) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: tapSite[0],
        line: 1,
        what: `an audio tap is installed in ${tapSite[0]} but nothing routes termination signals to NSApp.terminate`,
        why: rule.why,
        fix: 'in `main.swift`, map [SIGTERM, SIGINT, SIGHUP] to `DispatchSource.makeSignalSource(signal:queue:)` handlers that call `NSApp.terminate(nil)`, calling `signal(sig, SIG_IGN)` first and holding the sources in a top-level `let` so they outlive setup',
        doc: rule.doc,
      }];
    }

    const out = [];
    for (const [file, text] of routing) {
      const missing = REQUIRED_SIGNALS.filter((s) => !new RegExp(`\\b${s}\\b`).test(text));
      if (missing.length > 0) {
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: text.slice(0, text.search(/\bmakeSignalSource\s*\(/)).split('\n').length,
          what: `signal routing in ${file} does not cover ${missing.join(', ')}`,
          why: rule.why,
          fix: `add ${missing.join(', ')} to the routed set — each of them is fatal by default and leaves the tap installed`,
          doc: rule.doc,
        });
      }

      const ignore = text.search(/\bsignal\s*\([^)]*SIG_IGN/);
      const resume = text.search(/\.resume\s*\(\s*\)/);
      if (resume >= 0 && (ignore < 0 || ignore > resume)) {
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: text.slice(0, resume).split('\n').length,
          what: ignore < 0
            ? `${file} resumes a signal source without ever calling signal(…, SIG_IGN)`
            : `${file} calls signal(…, SIG_IGN) only after resume()`,
          why: rule.why,
          fix: 'call `signal(sig, SIG_IGN)` before `source.resume()` — until the default action is ignored, a signal arriving in the gap still terminates the process outright',
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;

import engineConstructionConfined from './engine-construction-confined.mjs';
import signalTeardownRouting from './signal-teardown-routing.mjs';
import noSuddenTermination from './no-sudden-termination.mjs';

// The macOS microphone lifecycle, as a pack: AVAudioEngine, CoreAudio device
// state, and the sleep/wake and exit paths around them. LaughCounter holds a
// real mic open for hours and has repeatedly left one *wedged* — dead
// system-wide until re-plugged — so this is a technology domain with its own
// hard-won rules, none of which the canon shelf homes.
//
// The case history stays in `dev/procedures/mac-audio-lifecycle.md` (routed from
// the project CLAUDE.md); this pack carries the invariants and enforces the
// three that a scan can decide.
//
// A local pack: declared by hand as `local/macos-audio-lifecycle`, never
// fingerprinted (detect/marker null).
export default {
  id: 'macos-audio-lifecycle',
  ruleRoutingGuidance: {
    belongs:
      'holding a macOS microphone safely — AVAudioEngine and CoreAudio device lifecycle, mic availability probing, sleep/wake and exit teardown, and the diagnostics that judge whether audio is really arriving',
    excludes:
      'the promise that what the mic hears never leaves the machine (that is on-device-privacy), and the repo\'s general build/packaging and check-authoring lessons (those are laughcounter)',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [engineConstructionConfined, signalTeardownRouting, noSuddenTermination],
};

// Red-first fixtures for the macos-audio-lifecycle checks: each rule must fire on
// a violating file and stay quiet on the repo's real, clean ones. Run directly:
//
//   node --test .claudinite/local/packs/macos-audio-lifecycle/pack.test.mjs
//
// They live here rather than in tests/ (`claudinite-isolation`). The fake ctx is
// the slice of the engine's context a check actually uses — `files` and `read` —
// so these tests need neither the canon mount nor a git checkout.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import engineConstructionConfined from './engine-construction-confined.mjs';
import signalTeardownRouting from './signal-teardown-routing.mjs';
import noSuddenTermination from './no-sudden-termination.mjs';

const repoRoot = dirname(dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))));

// Fixture ctx: an in-memory tree of { path: contents }.
const ctxOf = (tree) => ({
  files: Object.keys(tree),
  read: (path) => tree[path] ?? null,
});

// The real tree, so a rule that starts firing on the actual sources fails here.
const realCtx = (...paths) => ctxOf(Object.fromEntries(
  paths.map((p) => [p, readFileSync(join(repoRoot, p), 'utf8')])
));

const REAL_SWIFT = [
  'mac/Sources/LaughCounter/AppDelegate.swift',
  'mac/Sources/LaughCounter/AppLog.swift',
  'mac/Sources/LaughCounter/AudioDiagnostics.swift',
  'mac/Sources/LaughCounter/AudioHub.swift',
  'mac/Sources/LaughCounter/Chime.swift',
  'mac/Sources/LaughCounter/LaughCounter.swift',
  'mac/Sources/LaughCounter/LaughDetector.swift',
  'mac/Sources/LaughCounter/Store.swift',
  'mac/Sources/LaughCounter/VoiceCommand.swift',
  'mac/Sources/LaughCounter/main.swift',
];

test('engine-construction-confined fires on an engine built outside AudioHub', () => {
  const findings = engineConstructionConfined.run(ctxOf({
    'mac/Sources/LaughCounter/MicProbe.swift':
      'import AVFoundation\n'
      + 'func micExists() -> Bool {\n'
      + '    let probe = AVAudioEngine()\n'
      + '    return probe.inputNode.inputFormat(forBus: 0).sampleRate > 0\n'
      + '}\n',
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 3);
  assert.match(findings[0].what, /outside mac\/Sources\/LaughCounter\/AudioHub\.swift/);
});

test('engine-construction-confined ignores mentions that are not constructions', () => {
  const findings = engineConstructionConfined.run(ctxOf({
    'mac/Sources/LaughCounter/AppDelegate.swift':
      'private var engine: AVAudioEngine?\n'
      + '// (Re)starting the engine posts .AVAudioEngineConfigurationChange.\n'
      + 'NotificationCenter.default.addObserver(forName: .AVAudioEngineConfigurationChange, object: nil, queue: .main) { _ in }\n',
  }));
  assert.deepEqual(findings, []);
});

test('engine-construction-confined stays quiet on the real sources', () => {
  assert.deepEqual(engineConstructionConfined.run(realCtx(...REAL_SWIFT)), []);
});

test('signal-teardown-routing fires when a tap is installed and nothing routes signals', () => {
  const findings = signalTeardownRouting.run(ctxOf({
    'mac/Sources/LaughCounter/AudioHub.swift':
      'input.installTap(onBus: 0, bufferSize: 8192, format: format) { _, _ in }\n',
    'mac/Sources/LaughCounter/main.swift': 'let app = NSApplication.shared\napp.run()\n',
  }));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /nothing routes termination signals/);
});

test('signal-teardown-routing fires on SIG_IGN after resume(), and on a missing signal', () => {
  const findings = signalTeardownRouting.run(ctxOf({
    'mac/Sources/LaughCounter/AudioHub.swift':
      'input.installTap(onBus: 0, bufferSize: 8192, format: format) { _, _ in }\n',
    'mac/Sources/LaughCounter/main.swift':
      'let sources: [DispatchSourceSignal] = [SIGTERM, SIGINT].map { sig in\n'
      + '    let source = DispatchSource.makeSignalSource(signal: sig, queue: .main)\n'
      + '    source.setEventHandler { NSApp.terminate(nil) }\n'
      + '    source.resume()\n'
      + '    signal(sig, SIG_IGN)\n'
      + '    return source\n'
      + '}\n',
  }));
  assert.equal(findings.length, 2);
  assert.match(findings[0].what, /does not cover SIGHUP/);
  assert.match(findings[1].what, /only after resume\(\)/);
  assert.equal(findings[1].line, 4);
});

test('signal-teardown-routing says nothing about a tree that installs no tap', () => {
  assert.deepEqual(signalTeardownRouting.run(ctxOf({
    'mac/Sources/LaughCounter/main.swift': 'let app = NSApplication.shared\napp.run()\n',
  })), []);
});

test('signal-teardown-routing stays quiet on the real sources', () => {
  assert.deepEqual(signalTeardownRouting.run(realCtx(...REAL_SWIFT)), []);
});

test('no-sudden-termination fires on a plist that opts in', () => {
  const findings = noSuddenTermination.run(ctxOf({
    'mac/Resources/Info.plist':
      '<dict>\n'
      + '    <key>LSUIElement</key>\n'
      + '    <true/>\n'
      + '    <key>NSSupportsSuddenTermination</key>\n'
      + '    <true/>\n'
      + '</dict>\n',
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 4);
});

test('no-sudden-termination stays quiet on the real Info.plist', () => {
  assert.deepEqual(noSuddenTermination.run(realCtx('mac/Resources/Info.plist')), []);
});

